$connection->beginTransaction();try{$customer=$create->execute(new CreateCustomerCommand($uniqueName,$uniqueName.' B.V.','87654321','NL008765432B01',[['name'=>'Quote Contact','email'=>'quote-selector@example.test','phone'=>'030-8765432']],[['type'=>'billing','line_1'=>'Offertelaan 9','postal_code'=>'9000 ZZ','city'=>'Utrecht','country_code'=>'NL']]));$results=$provider->search('9c41e2',10);adminCustomerAssert(count($results)===1,'Echte Quote-providerzoekopdracht moet tenantklant vinden.');adminCustomerAssert($results[0]->getPublicId()===$customer->getPublicId(),'Quote-provider moet publieke klant-id teruggeven.');adminCustomerAssert($results[0]->getParty()['email']==='quote-selector@example.test','Quote-provider moet primair contact kopiëren.');adminCustomerAssert($results[0]->getBillingAddress()['line_1']==='Offertelaan 9','Quote-provider moet primair factuuradres kopiëren.');$found=$provider->find($customer->getPublicId());adminCustomerAssert($found!==null&&$found->getParty()['name']===$uniqueName.' B.V.','Quote-provider-find moet dezelfde tenantselectie leveren.');$connection->rollBack();}catch(Throwable $throwable){if($connection->inTransaction()){$connection->rollBack();}throw$throwable;}
